const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const zimbabwe = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Zimbabwe'))
    .geometry();

  const date2023Start = '2023-02-01';
  const date2023End = '2023-02-28';
  const date2024Start = '2024-02-01';
  const date2024End = '2024-02-29';

  // 2. Data Acquisition & Check
  const chirps2023 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(date2023Start, date2023End)
    .filterBounds(zimbabwe);

  const chirps2024 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(date2024Start, date2024End)
    .filterBounds(zimbabwe);

  const size2023 = await chirps2023.size().getInfo();
  const size2024 = await chirps2024.size().getInfo();

  console.log(`Feb 2023 Images: ${size2023}`);
  console.log(`Feb 2024 Images: ${size2024}`);

  if (size2023 === 0 || size2024 === 0) {
    console.log("No data available for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation for each period
  const precip2023 = chirps2023.sum().select('precipitation');
  const precip2024 = chirps2024.sum().select('precipitation');

  // Check pixel counts
  const count2023 = await precip2023.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: zimbabwe,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const count2024 = await precip2024.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: zimbabwe,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Feb 2023 Valid Pixels: ${count2023}`);
  console.log(`Feb 2024 Valid Pixels: ${count2024}`);

  if (count2023 === 0 || count2024 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculate mean total precipitation
  const stats2023 = await precip2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: zimbabwe,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const stats2024 = await precip2024.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: zimbabwe,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Feb 2023 Mean Total Precip: ${stats2023 !== null ? stats2023.toFixed(2) : 'null'} mm`);
  console.log(`Feb 2024 Mean Total Precip: ${stats2024 !== null ? stats2024.toFixed(2) : 'null'} mm`);

  // 5. Validation & Final Answer
  if (stats2023 === null || stats2024 === null || 
      isNaN(stats2023) || isNaN(stats2024) ||
      stats2023 < 0 || stats2024 < 0) {
    console.log("Calculation failed or invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  const decrease = stats2024 < stats2023;
  const percentChange = ((stats2024 - stats2023) / stats2023 * 100).toFixed(1);
  console.log(`Change: ${percentChange}%`);

  if (decrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
